#!/usr/bin/env python3
"""Writes ar.js: the runtime translator for Arabic pages, with its dictionary from data/i18n/src/ar-*.json."""
import json
from pathlib import Path
ROOT = Path(__file__).resolve().parent.parent.parent
core = json.loads((ROOT / "data/i18n/src/ar-core.json").read_text(encoding="utf-8"))
ui = json.loads((ROOT / "data/i18n/src/ar-ui.json").read_text(encoding="utf-8"))
D = {k: v for k, v in core.items() if len(k) <= 80}
D.update(ui)
HEAD = '/* Arabic pages (X.ar.html): translates the Persian that scripts write after the page loads\n   (price strip, search, menus, sliders, quizzes), turns Persian digits into Western digits and\n   Iranian-calendar dates into Gregorian ones. The page text itself is translated at build time\n   by scripts/build_ar_pages.py. Generated by that script\'s companion; edit data/i18n/src/ar-*.json. */\n(function () {\n  var root = document.documentElement;\n  if (root.getAttribute("data-site-lang") !== "ar") return;\n  var D = '
TAIL = ';\n  var FA = /[\\u0600-\\u06FF]/;\n  var PFA = /[پچژگیکۀ\\u200c۰-۹]/;\n  var DIG = "۰۱۲۳۴۵۶۷۸۹";\n  function digits(s) { return s.replace(/[۰-۹]/g, function (d) { return DIG.indexOf(d); }).replace(/٬/g, ",").replace(/٫/g, "."); }\n  var START = { "فروردین": [3, 21], "اردیبهشت": [4, 21], "خرداد": [5, 22], "تیر": [6, 22], "مرداد": [7, 23], "شهریور": [8, 23], "مهر": [9, 23], "آبان": [10, 23], "آذر": [11, 22], "دی": [12, 22], "بهمن": [1, 21], "اسفند": [2, 20] };\n  var GM = ["يناير", "فبراير", "مارس", "أبريل", "مايو", "يونيو", "يوليو", "أغسطس", "سبتمبر", "أكتوبر", "نوفمبر", "ديسمبر"], DIN = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];\n  function greg(d, m) { var s = START[m], gm = s[0], gd = s[1] + (+d) - 1; while (gd > DIN[gm - 1]) { gd -= DIN[gm - 1]; gm = gm % 12 + 1; } return gd + " " + GM[gm - 1]; }\n  function mins(n) { n = +n; return n === 1 ? "دقيقة واحدة" : n === 2 ? "دقيقتان" : n <= 10 ? n + " دقائق" : n + " دقيقة"; }\n  var MON = Object.keys(START).join("|");\n  var RULES = [\n    [new RegExp("^(\\\\d+) (" + MON + ") · (\\\\d+) دقیقه مطالعه$"), function (m) { return greg(m[1], m[2]) + " · قراءة " + mins(m[3]); }],\n    [/^(\\d+) دقیقه مطالعه$/, function (m) { return "قراءة " + mins(m[1]); }],\n    [/^(\\d+) دقیقه$/, function (m) { return mins(m[1]); }],\n    [/^قدم (\\d+)$/, function (m) { return "الخطوة " + m[1]; }],\n    [new RegExp("^(\\\\d+) (" + MON + ")$"), function (m) { return greg(m[1], m[2]); }]\n  ];\n  // pieces that scripts glue into longer text\n  var FRAG = Object.keys(D).filter(function (k) { return k.length >= 2 && k.length <= 40 && (k !== k.trim() || /[:«»()]/.test(k)); }).sort(function (a, b) { return b.length - a.length; });\n  function tr(s) {\n    var t = s.replace(/\\s+/g, " ").trim();\n    if (!t || !FA.test(t)) return null;\n    var out = D[t];\n    if (out == null) {\n      var d = digits(t);\n      for (var i = 0; i < RULES.length && out == null; i++) { var m = d.match(RULES[i][0]); if (m) out = RULES[i][1](m); }\n      if (out == null && d !== t && D[d] != null) out = D[d];\n      if (out == null) {\n        if (t.length > 60 || !PFA.test(t)) return d !== t ? s.replace(/[۰-۹٬٫]/g, function (c) { return digits(c); }) : null;\n        out = d;\n        for (var j = 0; j < FRAG.length && PFA.test(out); j++) { if (out.indexOf(FRAG[j]) > -1) out = out.split(FRAG[j]).join(D[FRAG[j]]); }\n        if (out === t) return null;\n      }\n    }\n    var lead = s.match(/^\\s*/)[0], trail = s.match(/\\s*$/)[0];\n    return lead + out + trail;\n  }\n  var SKIP = { SCRIPT: 1, STYLE: 1, NOSCRIPT: 1, TEXTAREA: 1 };\n  function walk(node) {\n    if (node.nodeType === 3) { var o = tr(node.nodeValue); if (o != null && o !== node.nodeValue) node.nodeValue = o; return; }\n    if (node.nodeType !== 1 || SKIP[node.nodeName]) return;\n    ["aria-label", "placeholder", "title", "alt"].forEach(function (a) {\n      var v = node.getAttribute && node.getAttribute(a);\n      if (v && FA.test(v)) { var o = tr(v); if (o != null) node.setAttribute(a, o); }\n    });\n    for (var c = node.firstChild; c; c = c.nextSibling) walk(c);\n  }\n  function run() { walk(document.body); if (FA.test(document.title)) { var o = tr(document.title); if (o) document.title = o; } }\n  run();\n  var busy = false;\n  new MutationObserver(function (list) {\n    if (busy) return; busy = true;\n    list.forEach(function (m) {\n      if (m.type === "characterData") walk(m.target);\n      else { m.addedNodes.forEach(walk); if (m.type === "attributes") walk(m.target); }\n    });\n    busy = false;\n  }).observe(document.body, { childList: true, subtree: true, characterData: true, attributes: true, attributeFilter: ["aria-label", "placeholder", "title"] });\n  // the language menu marks Arabic as the current language\n  setTimeout(function () {\n    document.querySelectorAll(".lang-opt[data-code]").forEach(function (o) { o.setAttribute("aria-current", o.getAttribute("data-code") === "ar" ? "true" : "false"); });\n    var b = document.querySelector(".lang-btn"); if (b) b.setAttribute("aria-label", "اللغة");\n  }, 0);\n})();\n'
(ROOT / "ar.js").write_text(HEAD + json.dumps(D, ensure_ascii=False, separators=(",", ":")) + TAIL, encoding="utf-8")
print("ar.js", len(D), "strings")
